if (numberOfChecks <= 0) {
    return false;
}
std::random_device rd;
std::mt19937 gen(rd());
std::normal_distribution<double> nd(0.0, 1.0);
int insideCount = 0;
const CGALPoint origin(p.x(), p.y(), p.z());

for (int i = 0; i < numberOfChecks; ++i) {
    double dx, dy, dz, norm;
    do {
        dx = nd(gen);
        dy = nd(gen);
        dz = nd(gen);
        norm = std::sqrt(dx * dx + dy * dy + dz * dz);
    } while (norm == 0.0);
    CGALPoint dir(origin.x() + dx, origin.y() + dy, origin.z() + dz);
    CGALRay ray(origin, dir);
    std::size_t intersected = tree.number_of_intersected_primitives(ray);
    if (intersected % 2 == 1) {
        ++insideCount;
    }
}
return insideCount > numberOfChecks / 2;

